const form=document.querySelector("#form");const nome=document.querySelector("#nome");const tipo=document.querySelector("#tipo");const preco=document.querySelector("#preco");const limparCampo=(campo)=>{campo.value=""};form.addEventListener("submit",(e)=>{e.preventDefault();const valNome=nome.value.trim();const valTipo=Number.parseInt(tipo.value.trim());const valPreco=Number.parseFloat(preco.value.trim());if(!valNome||valNome.length>50){alternarModalMsg(!0,"Erro: O nome do produto é obrigatório e deve conter até 50 caracteres.");limparCampo(nome);return}
if(Number.isNaN(valTipo)||valTipo<1){alternarModalMsg(!0,"Erro: Tipo de produto inválido.");limparCampo(tipo);return}
if(Number.isNaN(valPreco)||valPreco<1||valPreco>999.99){alternarModalMsg(!0,"Erro: O preço do produto é obrigatório e deve ser um número entre 1 e 999,99.");limparCampo(preco);return}
form.submit()})